function wRender(){$('#wpChips').innerHTML=['전체','근거리','원거리','지원'].map(c=>`<button type="button" class="${c===wf?'on':''}" data-c="${c}">${c}</button>`).join('');
  $('#wpNote').innerHTML='클래스 메뉴: 관리 · 합성 · 도감 · 확정 · 초월자, 등급은 레전드리 · 유니크 · 에픽 · 레어 · 노멀. <b>등급 차이가 커요</b>: 에픽은 공격 속도 28% · 시전 속도 15% · HP 725~775 · 클래스 스킬 3개, 레어는 16% · 7% · HP 200~250에 <b>클래스 스킬이 없어요</b>. 레어는 이름 앞말만 보면 돼요: <b>무명</b>=공격, <b>중급</b>=명중·회피, <b>능숙한</b>=생존. 에픽끼리는 특화 옵션 2개로 갈려요. 클래스는 <b>소환 상품</b>으로도, <b>게임 플레이</b>로도 얻을 수 있어요. 3개월 차에 신규 클래스, 6개월 차에 새 무기 계열이 추가될 예정입니다.';$('#wpList').innerHTML=WEAPONS.filter(w=>wf==='전체'||w.f===wf).map(w=>`<div class="card wcard"><img class="wimg" loading="lazy" src="${IB}ui/sel-${w.k}.webp" alt="${w.n} 캐릭터" data-zoom="1"><div><h3 class="gt" style="font-size:24px;font-weight:900">${w.n}</h3><span class="pill">${w.role}</span><span class="pill">${w.f}</span><p style="margin:6px 0 10px">${w.d}</p>${(()=>{const L=CLS.filter(c=>c.w===w.n&&c.tier!=='레어');return L.length?'<div>'+L.map(c=>`<button type="button" class="cup" data-c="${c.id}" onclick="cdOpen('${c.id}')">${c.n}</button>`).join('')+'</div>':''})()}</div></div>`).join('')}
$('#wpChips').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;wf=b.dataset.c;wRender()});
