 const nk=(n)=>esc(n)+(/운영자/.test(n)?'<span class="adm">운영</span>':'');
 const isAdmin=()=>!!(user&&user.email===ADMIN);
 const err=e=>{const c=(e&&e.code)||'';if(/permission-denied/.test(c))return '너무 빨리 썼거나 권한이 없어요. 잠시 후 다시 해 주세요.';if(/unavailable|network/.test(c))return '연결이 불안정해요. 잠시 후 다시 해 주세요.';return '문제가 생겼어요: '+(c||e)};
 const need=()=>{if(!user){login();return false}if(!me){toast('닉네임을 먼저 정해 주세요');q('#cmNick')&&q('#cmNick').focus();return false}return true};
 async function boot(){if(started)return;started=true;
  try{const x=await window.__fb();A=x.A;F=x.F;auth=x.auth;db=x.db;
   A.onAuthStateChanged(auth,async u=>{user=u;me=null;if(u){try{const d=await F.getDoc(F.doc(db,'users',u.uid));me=d.exists()?d.data():null}catch(e){}}drawMe();if(curPost)openPost(curPost,true)});
   drawBoards();loadList(true);const p=new URLSearchParams(location.search).get('p');if(p)openPost(p);
  }catch(e){q('#cmMe').innerHTML='<span class="mute">커뮤니티 서버에 연결하지 못했어요. 새로고침해 주세요.</span>';q('#cmList').innerHTML='<p class="mute">글을 불러오지 못했어요.</p>'}}
 function login(){const p=new A.GoogleAuthProvider();p.setCustomParameters({prompt:'select_account'});A.signInWithPopup(auth,p).catch(e=>{if(/popup-blocked|operation-not-supported/.test(e.code||''))A.signInWithRedirect(auth,p);else if(!/popup-closed|cancelled/.test(e.code||''))toast(err(e))})}
 function drawMe(){const box=q('#cmMe');
  if(!user){box.innerHTML='<span class="who">로그인하면 글 · 댓글 · 채팅을 쓸 수 있어요</span><button type="button" class="gbtn" id="cmLogin"><svg viewBox="0 0 48 48"><path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9 3.5l6.7-6.7C35.6 2.4 30.2 0 24 0 14.6 0 6.6 5.4 2.6 13.3l7.8 6C12.3 13.6 17.7 9.5 24 9.5z"/><path fill="#4285F4" d="M46.1 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.4c-.5 2.9-2.2 5.3-4.6 6.9l7.4 5.7c4.3-4 6.9-9.9 6.9-17.1z"/><path fill="#FBBC05" d="M10.4 28.7c-.5-1.4-.8-3-.8-4.7s.3-3.2.8-4.7l-7.8-6C1 16.5 0 20.1 0 24s1 7.5 2.6 10.7l7.8-6z"/><path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.4-5.7c-2.1 1.4-4.8 2.3-8.5 2.3-6.3 0-11.7-4.1-13.6-9.8l-7.8 6C6.6 42.6 14.6 48 24 48z"/></svg>구글로 로그인</button>';q('#cmLogin').onclick=login}
  else if(!me){box.innerHTML='<form id="cmNickF" style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;width:100%"><span class="who">사용할 닉네임</span><input id="cmNick" maxlength="12" placeholder="2~12자" style="flex:1;min-width:140px"><button type="submit">정하기</button><button type="button" class="ghost" id="cmOut">로그아웃</button></form>';
   q('#cmOut').onclick=()=>A.signOut(auth);
   q('#cmNickF').onsubmit=async e=>{e.preventDefault();const n=q('#cmNick').value.trim();if(n.length<2){toast('닉네임은 2자 이상');return}
    try{await F.setDoc(F.doc(db,'users',user.uid),{nick:n,createdAt:F.serverTimestamp()});me={nick:n};drawMe();toast('반가워요, '+n+'님!')}catch(x){toast(/permission/.test(x.code||'')?'쓸 수 없는 닉네임이에요 (운영자 · 관리자 등)':err(x))}}}
  else{box.innerHTML='<span class="who">'+nk(me.nick)+' <small>님 로그인 중</small></span><span style="display:flex;gap:6px">'+(isAdmin()?'<button type="button" class="ghost" id="cmReports">신고 목록</button>':'')+'<button type="button" class="ghost" id="cmOut">로그아웃</button></span>';
   q('#cmOut').onclick=()=>A.signOut(auth);if(isAdmin())q('#cmReports').onclick=showReports}
  const ci=q('#cmChatIn');ci.placeholder=user&&me?'메시지 입력 (200자)':'로그인하면 채팅할 수 있어요'}
 function drawBoards(){q('#cmBoards').innerHTML=Object.entries(BOARDS).map(([k,v])=>'<button type="button" data-b="'+k+'" class="'+(k===board?'on':'')+'">'+v+'</button>').join('')}
 async function loadList(reset){const L=q('#cmList');if(reset){last=null;L.innerHTML='<p class="mute">불러오는 중…</p>'}
  try{const parts=[F.collection(db,'posts')];if(board!=='all')parts.push(F.where('board','==',board));parts.push(F.orderBy('createdAt','desc'));if(last)parts.push(F.startAfter(last));parts.push(F.limit(20));
   const snap=await F.getDocs(F.query(...parts));if(reset)L.innerHTML='';last=snap.docs[snap.docs.length-1]||last;q('#cmMore').hidden=snap.docs.length<20;
   const rows=snap.docs.filter(d=>!d.data().deleted).map(d=>{const p=d.data();return '<div class="cmrow" data-p="'+d.id+'"><span class="bd">'+(BOARDS[p.board]||'')+(p.server?' · '+esc(p.server):'')+'</span><span class="tt">'+esc(p.title)+(p.comments?'<em>['+p.comments+']</em>':'')+'</span><span class="lk">'+(p.likes?'♥ '+p.likes:'')+'</span><span class="mt">'+nk(p.nick)+' · '+ago(p.createdAt)+'</span></div>'}).join('');
   L.insertAdjacentHTML('beforeend',rows);if(!L.children.length)L.innerHTML='<p class="mute" style="padding:18px 0;text-align:center">아직 글이 없어요. 첫 글을 남겨 주세요!</p>'}
  catch(e){L.innerHTML='<p class="mute">'+err(e)+'</p>'}}
 function show(which){q('#cmBoardWrap').hidden=which!=='list';q('#cmPost').hidden=which!=='post';q('#cmWrite').hidden=which!=='write';q('#cmChatWrap').hidden=which!=='chat';if(which!=='chat'&&unsub){unsub();unsub=null}}
 function setUrl(p){try{const u=new URL(location.href);if(p)u.searchParams.set('p',p);else u.searchParams.delete('p');history.replaceState(history.state,'',u.pathname+u.search+u.hash)}catch(e){}}
 async function openPost(id,keep){curPost=id;setUrl(id);const P=q('#cmPost');if(!keep){show('post');P.innerHTML='<p class="mute">불러오는 중…</p>';window.scrollTo(0,root.offsetTop)}
  try{const d=await F.getDoc(F.doc(db,'posts',id));if(!d.exists()||d.data().deleted){P.innerHTML='<p>삭제되었거나 없는 글이에요.</p><button type="button" class="ghost" id="cmBack">목록으로</button>';q('#cmBack').onclick=back;return}
   const p=d.data();let liked=false;if(user){try{liked=(await F.getDoc(F.doc(db,'likes',id+'_'+user.uid))).exists()}catch(e){}}
   const mine=user&&p.uid===user.uid;
   const cs=await F.getDocs(F.query(F.collection(db,'posts',id,'comments'),F.orderBy('createdAt','asc'),F.limit(300)));
   P.innerHTML='<button type="button" class="ghost" id="cmBack">← 목록</button><h2>'+esc(p.title)+'</h2><div class="mt">'+(BOARDS[p.board]||'')+(p.server?' · '+esc(p.server):'')+' · '+nk(p.nick)+' · '+ago(p.createdAt)+(p.editedAt?' · 수정됨':'')+'</div><div class="cmbody">'+link(p.body)+'</div>'
    +'<div class="cmact"><button type="button" class="like '+(liked?'on':'')+'" id="cmLike">♥ 추천 '+(p.likes||0)+'</button><button type="button" id="cmShare">🔗 링크 복사</button><button type="button" id="cmRep">🚩 신고</button>'+(mine?'<button type="button" id="cmEdit">수정</button>':'')+(mine||isAdmin()?'<button type="button" id="cmDel">삭제</button>':'')+(isAdmin()&&!mine?'<button type="button" id="cmBan">작성자 차단</button>':'')+'</div>'
    +'<h3 style="margin:18px 0 4px">댓글 '+(p.comments||0)+'</h3><div id="cmCs">'+cs.docs.map(c=>{const x=c.data();if(x.deleted)return '<div class="cmc"><p class="mute">삭제된 댓글이에요</p></div>';return '<div class="cmc">'+((user&&x.uid===user.uid)||isAdmin()?'<button type="button" class="x" data-cd="'+c.id+'">삭제</button>':'')+'<button type="button" class="x" data-cr="'+c.id+'">신고</button><b>'+nk(x.nick)+'</b><small>'+ago(x.createdAt)+'</small><p>'+link(x.body)+'</p></div>'}).join('')+'</div>'
    +'<form class="cmform" id="cmCForm" autocomplete="off"><input id="cmCIn" maxlength="1000" placeholder="'+(user&&me?'댓글 쓰기':'로그인하면 댓글을 쓸 수 있어요')+'"><button type="submit">등록</button></form>';
   q('#cmBack').onclick=back;
   q('#cmShare').onclick=()=>{const u=location.origin+'/community/?p='+id;(navigator.clipboard?navigator.clipboard.writeText(u):Promise.reject()).then(()=>toast('링크를 복사했어요'),()=>prompt('링크',u))};
   q('#cmLike').onclick=async()=>{if(!need())return;if(liked){toast('이미 추천했어요');return}try{const b=F.writeBatch(db);b.set(F.doc(db,'likes',id+'_'+user.uid),{pid:id,uid:user.uid,createdAt:F.serverTimestamp()});b.update(F.doc(db,'posts',id),{likes:F.increment(1)});await b.commit();openPost(id,true)}catch(e){toast(err(e))}};
   q('#cmRep').onclick=()=>report('post','posts/'+id);
   if(q('#cmDel'))q('#cmDel').onclick=async()=>{if(!confirm('이 글을 삭제할까요?'))return;try{await F.updateDoc(F.doc(db,'posts',id),{deleted:true});toast('삭제했어요');back()}catch(e){toast(err(e))}};
   if(q('#cmEdit'))q('#cmEdit').onclick=()=>openWrite({id,...p});
   if(q('#cmBan'))q('#cmBan').onclick=async()=>{if(!confirm(p.nick+' 님을 차단할까요? (글쓰기 · 채팅 금지)'))return;try{await F.setDoc(F.doc(db,'bans',p.uid),{nick:p.nick,at:F.serverTimestamp()});toast('차단했어요')}catch(e){toast(err(e))}};
   q('#cmCs').onclick=async e=>{const cd=e.target.dataset.cd,cr=e.target.dataset.cr;if(cr)report('comment','posts/'+id+'/comments/'+cr);if(cd){if(!confirm('댓글을 삭제할까요?'))return;try{await F.updateDoc(F.doc(db,'posts',id,'comments',cd),{deleted:true});openPost(id,true)}catch(x){toast(err(x))}}};
   q('#cmCForm').onsubmit=async e=>{e.preventDefault();if(!need())return;const t=q('#cmCIn').value.trim();if(!t)return;try{const b=F.writeBatch(db);b.set(F.doc(F.collection(db,'posts',id,'comments')),{body:t,nick:me.nick,uid:user.uid,createdAt:F.serverTimestamp(),deleted:false});b.update(F.doc(db,'posts',id),{comments:F.increment(1)});b.update(F.doc(db,'users',user.uid),{lastComment:F.serverTimestamp()});await b.commit();openPost(id,true)}catch(x){toast(err(x))}};
  }catch(e){P.innerHTML='<p class="mute">'+err(e)+'</p><button type="button" class="ghost" id="cmBack">목록으로</button>';q('#cmBack').onclick=back}}
 function back(){curPost=null;setUrl(null);show('list');loadList(true)}
 async function report(kind,path){if(!need())return;const r=prompt('신고 이유를 적어 주세요 (욕설, 광고, 도배 등)');if(!r||!r.trim())return;try{const b=F.writeBatch(db);b.set(F.doc(F.collection(db,'reports')),{kind,path,reason:r.trim().slice(0,300),uid:user.uid,createdAt:F.serverTimestamp()});b.update(F.doc(db,'users',user.uid),{lastReport:F.serverTimestamp()});await b.commit();toast('신고했어요. 운영자가 확인할게요')}catch(e){toast(err(e))}}
 async function showReports(){show('post');curPost=null;const P=q('#cmPost');P.innerHTML='<p class="mute">불러오는 중…</p>';try{const s=await F.getDocs(F.query(F.collection(db,'reports'),F.orderBy('createdAt','desc'),F.limit(50)));
   P.innerHTML='<button type="button" class="ghost" id="cmBack">← 목록</button><h2>신고 목록 (운영자)</h2>'+(s.docs.map(d=>{const r=d.data();const pid=r.path.split('/')[1];return '<div class="cmc"><button type="button" class="x" data-rd="'+d.id+'">처리 완료</button><b>'+esc(r.kind)+'</b><small>'+ago(r.createdAt)+'</small><p>'+esc(r.reason)+'<br><a href="?p='+esc(pid)+'" data-op="'+esc(pid)+'">'+esc(r.path)+'</a></p></div>'}).join('')||'<p class="mute">신고가 없어요.</p>');
   q('#cmBack').onclick=back;P.onclick=async e=>{const rd=e.target.dataset.rd,op=e.target.dataset.op;if(op){e.preventDefault();P.onclick=null;openPost(op)}if(rd){await F.deleteDoc(F.doc(db,'reports',rd));showReports()}}}catch(e){P.innerHTML='<p class="mute">'+err(e)+'</p>'}}
 function openWrite(edit){if(!need())return;show('write');curPost=null;const W=q('#cmWrite');W.dataset.edit=edit?edit.id:'';q('#cmWriteH').textContent=edit?'글 수정':'글쓰기';
  q('#cmWBoard').value=edit?edit.board:(board==='all'?'free':board);q('#cmWBoard').disabled=!!edit;q('#cmWServer').value=edit?edit.server||'':'';q('#cmWTitle').value=edit?edit.title:'';q('#cmWBody').value=edit?edit.body:'';q('#cmWServerBox').hidden=q('#cmWBoard').value!=='guild';window.scrollTo(0,root.offsetTop)}
 q('#cmWBoard').onchange=()=>{q('#cmWServerBox').hidden=q('#cmWBoard').value!=='guild'};
 q('#cmWCancel').onclick=()=>{const id=q('#cmWrite').dataset.edit;id?openPost(id):back()};
 q('#cmWrite').onsubmit=async e=>{e.preventDefault();if(!need())return;const t=q('#cmWTitle').value.trim(),bd=q('#cmWBody').value.trim(),bo=q('#cmWBoard').value,sv=bo==='guild'?q('#cmWServer').value.trim().slice(0,12):'';
  if(t.length<2||bd.length<2){toast('제목과 내용을 2자 이상 써 주세요');return}const btn=q('#cmWSubmit');btn.disabled=true;
  try{const id=q('#cmWrite').dataset.edit;if(id){await F.updateDoc(F.doc(db,'posts',id),{title:t,body:bd,editedAt:F.serverTimestamp()});openPost(id)}
   else{const ref=F.doc(F.collection(db,'posts'));const b=F.writeBatch(db);b.set(ref,{board:bo,server:sv,title:t,body:bd,nick:me.nick,uid:user.uid,createdAt:F.serverTimestamp(),likes:0,comments:0,deleted:false});b.update(F.doc(db,'users',user.uid),{lastPost:F.serverTimestamp()});await b.commit();toast('글을 올렸어요');openPost(ref.id)}}
  catch(x){toast(err(x))}finally{btn.disabled=false}};
 q('#cmBoards').onclick=e=>{const b=e.target.closest('button');if(!b)return;board=b.dataset.b;drawBoards();show('list');curPost=null;setUrl(null);loadList(true)};
 q('#cmMore').onclick=()=>loadList(false);
 q('#cmList').onclick=e=>{const r=e.target.closest('.cmrow');if(r)openPost(r.dataset.p)};
 q('#cmWriteBtn').onclick=()=>openWrite(null);
 q('#cmTabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;[...q('#cmTabs').children].forEach(x=>x.classList.toggle('on',x===b));if(b.dataset.t==='chat'){show('chat');drawRooms();listen()}else{show('list');loadList(true)}};
 function drawRooms(){q('#cmRooms').innerHTML=Object.entries(ROOMS).map(([k,v])=>'<button type="button" data-r="'+k+'" class="'+(k===room?'on':'')+'">'+v+'</button>').join('')}
 q('#cmRooms').onclick=e=>{const b=e.target.closest('button');if(!b)return;room=b.dataset.r;drawRooms();listen()};
 function listen(){if(!F)return;if(unsub)unsub();const M=q('#cmMsgs');M.innerHTML='<p class="mute">불러오는 중…</p>';
  unsub=F.onSnapshot(F.query(F.collection(db,'chats',room,'msgs'),F.orderBy('createdAt','desc'),F.limit(60)),snap=>{const ds=snap.docs.slice().reverse();
   M.innerHTML=ds.map(d=>{const m=d.data();const mine=user&&m.uid===user.uid;return '<div class="cmmsg'+(mine?' mine':'')+'"><b>'+nk(m.nick)+'</b>'+link(m.text)+'<small>'+ago(m.createdAt)+'</small>'+(mine||isAdmin()?'<button type="button" class="x" data-md="'+d.id+'">삭제</button>':'<button type="button" class="x" data-mr="'+d.id+'">신고</button>')+'</div>'}).join('')||'<p class="mute" style="text-align:center;margin:auto">아직 대화가 없어요. 먼저 인사해 보세요!</p>';M.scrollTop=M.scrollHeight},e=>{M.innerHTML='<p class="mute">'+err(e)+'</p>'})}
 q('#cmMsgs').onclick=async e=>{const md=e.target.dataset.md,mr=e.target.dataset.mr;if(mr)report('chat','chats/'+room+'/msgs/'+mr);if(md){try{await F.deleteDoc(F.doc(db,'chats',room,'msgs',md))}catch(x){toast(err(x))}}};
 q('#cmChatForm').onsubmit=async e=>{e.preventDefault();if(!need())return;const i=q('#cmChatIn'),t=i.value.trim();if(!t)return;
  try{const b=F.writeBatch(db);b.set(F.doc(F.collection(db,'chats',room,'msgs')),{text:t.slice(0,200),nick:me.nick,uid:user.uid,createdAt:F.serverTimestamp()});b.update(F.doc(db,'users',user.uid),{lastChat:F.serverTimestamp()});await b.commit();i.value=''}catch(x){toast(err(x))}};
 const go=()=>{if(location.hash==='#community'||window.START==='community')boot()};go();window.addEventListener('hashchange',go);
