let vdf='전체';
const vCard=v=>`<a class="vc" href="https://www.youtube.com/watch?v=${v[0]}" target="_blank" rel="noopener"><div class="th" style="background-image:url(https://i.ytimg.com/vi/${v[0]}/hqdefault.jpg)"><span class="vb">조회수 ${v[3]}</span><span class="du">${v[4]}</span></div><h3>${v[1]}</h3><p>${v[2]==='공식'?'템빨: 오버기어드 공식':v[2]} · ${v[5]}</p></a>`;
function vdRender(){const cs=['전체','입문','클래스','리뷰','원작','공식'];$('#vdChips').innerHTML=cs.map(c=>`<button type="button" class="${c===vdf?'on':''}" data-c="${c}">${c}</button>`).join('');
  $('#vdList').innerHTML=VIDS.filter(v=>vdf==='전체'||v[5]===vdf).map(vCard).join('')}
$('#vdChips').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;vdf=b.dataset.c;vdRender()});
vdRender();
if($('#homeVids'))$('#homeVids').innerHTML=VIDS.filter(v=>v[5]!=='공식').slice(0,6).map(vCard).join('');

