const tnCube=(()=>{const K='tn_cube';let M={};try{M=JSON.parse(localStorage.getItem(K)||'{}')||{}}catch(e){}
 const k=(r,i)=>r+'|'+i,ak=r=>r==='크라임 숲'?'크라임숲':r;
 const sync=r=>{try{const A=JSON.parse(localStorage.getItem('dn-arc')||'{}');const o=A[ak(r)]||(A[ak(r)]={c:0,t:0,h:0,m:0,d:0,s:0});o.c=api.cnt(r);o.t=(CUBE[r]||[]).length;localStorage.setItem('dn-arc',JSON.stringify(A))}catch(e){}};
 const api={has:(r,i)=>!!M[k(r,i)],cnt:r=>(CUBE[r]||[]).filter((_,i)=>M[k(r,i)]).length,tot:r=>(CUBE[r]||[]).length,
  all:()=>Object.keys(CUBE).reduce((a,r)=>a+api.cnt(r),0),allT:()=>Object.keys(CUBE).reduce((a,r)=>a+api.tot(r),0),
  done:()=>Object.keys(CUBE).filter(r=>api.cnt(r)>=api.tot(r)).length,
  set:(r,i,v)=>{if(v)M[k(r,i)]=1;else delete M[k(r,i)];try{localStorage.setItem(K,JSON.stringify(M))}catch(e){}sync(r);document.dispatchEvent(new CustomEvent('tncube',{detail:{r,i,v}}));
   if(v&&api.cnt(r)>=api.tot(r)){const d=document.createElement('div');d.className='dqtoast';d.innerHTML='🎉 <b>'+r+'</b> 데이터 큐브 '+api.tot(r)+'개 전부 찾았어요! 지역 완료';document.body.appendChild(d);requestAnimationFrame(()=>d.classList.add('on'));setTimeout(()=>{d.classList.remove('on');setTimeout(()=>d.remove(),400)},3800)}},
  name:(r,i)=>{const nm=x=>String(x||'').replace(/<[^>]+>/g,'').split(' — ')[0],L=(CUBE[r]||[]).map(nm),a=L[i];if(L.filter(x=>x===a).length<2)return a;return a+' '+'①②③'[L.slice(0,i).filter(x=>x===a).length]}};
 return api})();
const cmSvg=n=>{const m=CMAP[n];if(!m)return '';const e=x=>String(x).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));return '<svg class="cmap" viewBox="0 0 '+m.w+' '+m.h+'" role="img" aria-label="'+e(n)+' 데이터 큐브 위치 약도"><rect width="100%" height="100%" rx="10" fill="#0b1424"/>'+m.f.map(f=>'<ellipse cx="'+f[1]+'" cy="'+f[2]+'" rx="30" ry="20" fill="#ffffff0c" stroke="#ffffff22"/><text x="'+f[1]+'" y="'+(f[2]+30)+'" text-anchor="middle" font-size="10" fill="#9aa6b8">'+e(f[0])+'</text>').join('')+m.t.map(t=>'<rect x="'+(t[1]-5)+'" y="'+(t[2]-5)+'" width="10" height="10" fill="#7de0a8"/><text x="'+t[1]+'" y="'+(t[2]-9)+'" text-anchor="middle" font-size="10" fill="#7de0a8">'+e(t[0])+'</text>').join('')+m.b.map(b=>'<path d="M'+b[1]+' '+(b[2]-6)+'l6 6-6 6-6-6z" fill="#5aa7ff"/>').join('')+m.c.map(c=>{const ok=tnCube.has(n,c[0]-1);return '<circle cx="'+c[2]+'" cy="'+c[3]+'" r="8" fill="'+(ok?'#3fb96b':'#f0a23a')+'" stroke="#1b1206"/><text x="'+c[2]+'" y="'+(c[3]+4)+'" text-anchor="middle" font-size="10" font-weight="800" fill="#1b1206">'+(ok?'✓':c[0])+'</text>'}).join('')+'</svg><p class="small mute" style="margin:4px 0 0">🟠 큐브(번호는 위 목록 순서) · 🟢 찾은 큐브 · 🔷 거점 · 🟩 마을 · 흐린 원은 사냥터. 대략적인 약도예요.</p>'};
