 const g=n=>{const o=S[n]||(S[n]={c:0,t:0,h:0,m:0,d:0,s:0});if(cb(n)){o.c=tnCube.cnt(cbn(n));o.t=tnCube.tot(cbn(n))}return o};
 function draw(){let C=0,TT=0,H=0,D=0;T.innerHTML='<thead><tr><th>지역</th><th>데이터 큐브</th><th>전체</th><th>히든 퀘스트(S↑)</th><th>메인</th><th>도감</th><th>수집</th></tr></thead><tbody>'+R.map(([n,k])=>{const o=g(n),tot=o.t||k;C+=o.c;TT+=tot;H+=o.h;const done=tot>0&&o.c>=tot&&o.m&&o.d&&o.s;if(done)D++;return '<tr data-n="'+n+'" class="'+(done?'done':'')+'"><td><b>'+n+'</b>'+(k?' <small class="mute">('+k+'곳 확인)</small>':'')+'</td>'+(cb(n)?'<td><b style="color:'+(o.c>=tot?'#7de0a8':'inherit')+'">'+o.c+' / '+tot+'</b></td><td class="small mute">위 체크</td>':'<td><span class="cnt"><button type="button" data-a="c-">−</button><b>'+o.c+(tot?' / '+tot:'')+'</b><button type="button" data-a="c+">+</button></span></td><td><input type="number" min="0" max="99" data-a="t" value="'+(o.t||'')+'" placeholder="'+(k||'?')+'" aria-label="'+n+' 데이터 큐브 전체 개수"></td>')+'<td><span class="cnt"><button type="button" data-a="h-">−</button><b>'+o.h+'</b><button type="button" data-a="h+">+</button></span></td>'+['m','d','s'].map(x=>'<td><input type="checkbox" data-a="'+x+'"'+(o[x]?' checked':'')+' aria-label="'+n+' '+({m:'메인 퀘스트',d:'몬스터 도감',s:'수집'})[x]+' 완료"></td>').join('')+'</tr>'}).join('')+'</tbody>';
  const sm=document.getElementById('arcSum');if(sm)sm.textContent='· 큐브 '+C+(TT?' / '+TT:'')+'개 · 히든 '+H+'개 · 모두 끝낸 지역 '+D+' / '+R.length}
 T.onclick=e=>{const b=e.target.closest('button[data-a]');if(!b)return;const n=b.closest('tr').dataset.n,o=g(n),a=b.dataset.a,k=a[0],tot=o.t||(R.find(r=>r[0]===n)||[])[1]||99;if(a.endsWith('+'))o[k]=Math.min(k==='c'?tot:999,o[k]+1);else o[k]=Math.max(0,o[k]-1);sv();draw()};
 T.onchange=e=>{const i=e.target;if(!i.dataset.a)return;const n=i.closest('tr').dataset.n,o=g(n);if(i.type==='checkbox')o[i.dataset.a]=i.checked?1:0;else{o.t=Math.max(0,Math.min(99,parseInt(i.value)||0));if(o.t&&o.c>o.t)o.c=o.t}sv();draw()};
